CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('pharmacy','{"name":"Radefy Pharmacy","address":"","phone":"","logo":"","footer":"Thank you. Wishing you good health.","prefix":"INV","language":"en","calendar":"persian","timezone":"Asia/Kabul","expiry_days":90,"paper":"a4","columns":["unit","quantity","price","discount"],"backup_retention":30}');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,permissions TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(kind,name));
INSERT OR IGNORE INTO categories(kind,name) VALUES('supplier_type','Local'),('supplier_type','Imported'),('expense','Rent'),('expense','Utilities'),('expense','Salary'),('expense','Transport'),('expense','Other');
CREATE TABLE IF NOT EXISTS parties(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('customer','supplier')),name TEXT NOT NULL,search_name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',type_id INTEGER REFERENCES categories(id),balance_minor INTEGER NOT NULL DEFAULT 0,opening_minor INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS party_kind_name ON parties(kind,active,search_name,id);
CREATE INDEX IF NOT EXISTS party_kind_id ON parties(kind,id);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,search_name TEXT NOT NULL,generic TEXT NOT NULL DEFAULT '',strength TEXT NOT NULL DEFAULT '',form TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',manufacturer TEXT NOT NULL DEFAULT '',barcode TEXT UNIQUE,shelf TEXT NOT NULL DEFAULT '',base_unit TEXT NOT NULL DEFAULT 'tablet',reorder_level INTEGER NOT NULL DEFAULT 10,on_hand INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS product_name ON products(active,search_name,id);
CREATE INDEX IF NOT EXISTS product_low ON products(active,on_hand,reorder_level,id);
CREATE VIRTUAL TABLE IF NOT EXISTS product_search USING fts5(name,generic,search_name,content='products',content_rowid='id',prefix='2 3 4');
CREATE TRIGGER IF NOT EXISTS product_search_insert AFTER INSERT ON products BEGIN INSERT INTO product_search(rowid,name,generic,search_name) VALUES(new.id,new.name,new.generic,new.search_name); END;
CREATE TRIGGER IF NOT EXISTS product_search_delete AFTER DELETE ON products BEGIN INSERT INTO product_search(product_search,rowid,name,generic,search_name) VALUES('delete',old.id,old.name,old.generic,old.search_name); END;
CREATE TRIGGER IF NOT EXISTS product_search_update AFTER UPDATE OF name,generic,search_name ON products BEGIN INSERT INTO product_search(product_search,rowid,name,generic,search_name) VALUES('delete',old.id,old.name,old.generic,old.search_name); INSERT INTO product_search(rowid,name,generic,search_name) VALUES(new.id,new.name,new.generic,new.search_name); END;
CREATE TABLE IF NOT EXISTS product_units(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),name TEXT NOT NULL,multiplier INTEGER NOT NULL CHECK(multiplier>0),price_minor INTEGER NOT NULL CHECK(price_minor>=0),active INTEGER NOT NULL DEFAULT 1,UNIQUE(product_id,name));
CREATE INDEX IF NOT EXISTS units_product ON product_units(product_id,active,id);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('sale','purchase','customer_return','supplier_return')),number TEXT NOT NULL UNIQUE,party_id INTEGER REFERENCES parties(id),source_id INTEGER REFERENCES documents(id),date TEXT NOT NULL,subtotal_minor INTEGER NOT NULL,discount_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,paid_minor INTEGER NOT NULL DEFAULT 0,credit_minor INTEGER NOT NULL DEFAULT 0,outstanding_minor INTEGER NOT NULL DEFAULT 0,returned_minor INTEGER NOT NULL DEFAULT 0,cost_minor INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',pharmacy_snapshot TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS doc_kind_date ON documents(kind,date DESC,id DESC);
CREATE INDEX IF NOT EXISTS doc_kind_id ON documents(kind,id DESC);
CREATE INDEX IF NOT EXISTS doc_party_date ON documents(party_id,date DESC,id DESC);
CREATE INDEX IF NOT EXISTS doc_party_due ON documents(party_id,kind,id) WHERE outstanding_minor>0;
CREATE TABLE IF NOT EXISTS document_lines(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),product_id INTEGER NOT NULL REFERENCES products(id),source_line_id INTEGER REFERENCES document_lines(id),name TEXT NOT NULL,unit TEXT NOT NULL,multiplier INTEGER NOT NULL,quantity INTEGER NOT NULL,base_quantity INTEGER NOT NULL,price_minor INTEGER NOT NULL,discount_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,cost_minor INTEGER NOT NULL DEFAULT 0,returned_quantity INTEGER NOT NULL DEFAULT 0,batch_number TEXT,expiry TEXT,disposition TEXT);
CREATE INDEX IF NOT EXISTS lines_doc ON document_lines(document_id,id);
CREATE INDEX IF NOT EXISTS lines_product ON document_lines(product_id,document_id,id);
CREATE INDEX IF NOT EXISTS lines_source ON document_lines(source_line_id,id);
CREATE TABLE IF NOT EXISTS batches(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),purchase_line_id INTEGER REFERENCES document_lines(id),number TEXT NOT NULL,expiry TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),cost_minor INTEGER NOT NULL CHECK(cost_minor>=0),status TEXT NOT NULL DEFAULT 'sellable' CHECK(status IN ('sellable','quarantine')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS batch_fefo ON batches(product_id,status,expiry,id) WHERE quantity>0;
CREATE INDEX IF NOT EXISTS batch_expiry ON batches(status,expiry,id) WHERE quantity>0;
CREATE INDEX IF NOT EXISTS batch_source ON batches(purchase_line_id,id);
CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY,line_id INTEGER NOT NULL REFERENCES document_lines(id),batch_id INTEGER NOT NULL REFERENCES batches(id),quantity INTEGER NOT NULL,cost_minor INTEGER NOT NULL,returned_quantity INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS alloc_line ON allocations(line_id,id);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),batch_id INTEGER NOT NULL REFERENCES batches(id),document_id INTEGER REFERENCES documents(id),quantity INTEGER NOT NULL,cost_minor INTEGER NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS movement_product ON stock_movements(product_id,id DESC);
CREATE INDEX IF NOT EXISTS movement_date ON stock_movements(created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,party_id INTEGER REFERENCES parties(id),document_id INTEGER REFERENCES documents(id),kind TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),method TEXT NOT NULL,date TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pay_party_date ON payments(party_id,date DESC,id DESC);
CREATE INDEX IF NOT EXISTS pay_date ON payments(date DESC,id DESC);
CREATE TABLE IF NOT EXISTS payment_allocations(id INTEGER PRIMARY KEY,payment_id INTEGER NOT NULL REFERENCES payments(id),document_id INTEGER NOT NULL REFERENCES documents(id),amount_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS account_movements(id INTEGER PRIMARY KEY,party_id INTEGER NOT NULL REFERENCES parties(id),document_id INTEGER REFERENCES documents(id),payment_id INTEGER REFERENCES payments(id),amount_minor INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS account_party ON account_movements(party_id,id DESC);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,category_id INTEGER NOT NULL REFERENCES categories(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),date TEXT NOT NULL,method TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS expense_date ON expenses(date DESC,id DESC);
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,title TEXT NOT NULL,payload TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS draft_user ON drafts(user_id,updated_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS audit_date ON audit(created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_totals(date TEXT PRIMARY KEY,sales_minor INTEGER NOT NULL DEFAULT 0,purchases_minor INTEGER NOT NULL DEFAULT 0,returns_minor INTEGER NOT NULL DEFAULT 0,supplier_returns_minor INTEGER NOT NULL DEFAULT 0,cost_minor INTEGER NOT NULL DEFAULT 0,expenses_minor INTEGER NOT NULL DEFAULT 0,receipts_minor INTEGER NOT NULL DEFAULT 0,payments_minor INTEGER NOT NULL DEFAULT 0,discounts_minor INTEGER NOT NULL DEFAULT 0,sale_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS backups(id INTEGER PRIMARY KEY,backup_id TEXT NOT NULL,destination TEXT NOT NULL,path TEXT NOT NULL,automatic INTEGER NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',bytes INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(backup_id,destination));
CREATE INDEX IF NOT EXISTS backup_status ON backups(status,id DESC);

CREATE INDEX IF NOT EXISTS draft_cursor ON drafts(user_id,(updated_at || '|' || id) DESC);
CREATE INDEX IF NOT EXISTS batch_expiry_refresh ON batches(expiry,product_id) WHERE quantity>0 AND status='sellable';
CREATE INDEX IF NOT EXISTS party_name_search ON parties(kind,search_name,id);
CREATE INDEX IF NOT EXISTS pay_kind_id ON payments(kind,id);
